    double ux, uy, uz, cos_a, sin_a, udotv, n;
    adcs_vec3_t u, cross_uv, v_cos, cross_sin, u_udotv, term2, term3;

    if ((vector == NULL) || (axis == NULL) || (rotated == NULL))
        return ADCS_E_NULL;

    if ((!adcs_is_finite_vec3(vector)) || (!adcs_is_finite_vec3(axis)) ||
        (!isfinite(angle_rad)))
        return ADCS_E_RANGE;

    n = adcs_vec3_norm(axis);
    if (!isfinite(n) || (n <= ADCS_EPS_NORM)) {
        *rotated = (adcs_vec3_t){0, 0, 0};
        return ADCS_E_RANGE;
    }

    ux = axis->x / n;
    uy = axis->y / n;
    uz = axis->z / n;
    u = (adcs_vec3_t){ux, uy, uz};

    cos_a = cos(angle_rad);
    sin_a = sin(angle_rad);

    udotv = adcs_vec3_dot(&u, vector);

    cross_uv = adcs_vec3_cross(&u, vector);

    v_cos = adcs_vec3_scale(vector, cos_a);
    cross_sin = adcs_vec3_scale(&cross_uv, sin_a);
    u_udotv = adcs_vec3_scale(&u, udotv * (1.0 - cos_a));

    term2 = adcs_vec3_add(&v_cos, &cross_sin);
    term3 = adcs_vec3_add(&term2, &u_udotv);

    *rotated = term3;
    return ADCS_OK;
}

