    adcs_vec3_t u, uxv, term1, term2, term3, tmp;
    double c, s, udotv;

    if ((vector == NULL) || (axis == NULL) || (rotated == NULL)) {
        if (rotated != NULL) {
            rotated->x = 0.0;
            rotated->y = 0.0;
            rotated->z = 0.0;
        }
        return ADCS_E_NULL;
    }

    if ((!adcs_is_finite_vec3(vector)) || (!adcs_is_finite_vec3(axis)) ||
        (!isfinite(angle_rad))) {
        rotated->x = 0.0;
        rotated->y = 0.0;
        rotated->z = 0.0;
        return ADCS_E_RANGE;
    }

    if (adcs_vec3_normalize(axis, ADCS_EPS_NORM, &u) != ADCS_OK) {
        rotated->x = 0.0;
        rotated->y = 0.0;
        rotated->z = 0.0;
        return ADCS_E_RANGE;
    }

    c = cos(angle_rad);
    s = sin(angle_rad);
    udotv = adcs_vec3_dot(&u, vector);

    term1 = adcs_vec3_scale(vector, c);
    uxv = adcs_vec3_cross(&u, vector);
    term2 = adcs_vec3_scale(&uxv, s);
    term3 = adcs_vec3_scale(&u, udotv * (1.0 - c));

    tmp = adcs_vec3_add(&term1, &term2);
    *rotated = adcs_vec3_add(&tmp, &term3);

    return ADCS_OK;
}

